const query = $json.query ?? {};
const supportedFlows = new Set(['review', 'compliance', 'document', 'tests', 'batch', 'pull_request_review', 'pull_request_tests']);
function optionalString(value, field) { if (value === undefined || value === null) return undefined; if (typeof value !== 'string' || !value.trim()) throw new Error(`Query invalida para analytics: ${field}.`); return value.trim(); }
function optionalDate(value, field) { const text = optionalString(value, field); if (text === undefined) return undefined; if (Number.isNaN(Date.parse(value))) throw new Error(`Query invalida para analytics: ${field}.`); return new Date(text).toISOString(); }
function sql(value) { return String(value).replaceAll("'", "''"); }
const flowType = optionalString(query.flow_type, 'flow_type');
if (flowType !== undefined && !supportedFlows.has(flowType)) throw new Error('Query invalida para analytics: flow_type.');
const model = optionalString(query.model, 'model');
const from = optionalDate(query.from, 'from');
const to = optionalDate(query.to, 'to');
const conditions = [];
if (flowType !== undefined) conditions.push(`e.flow_type = '${sql(flowType)}'`);
if (model !== undefined) conditions.push(`t.model_requested = '${sql(model)}'`);
if (from !== undefined) conditions.push(`e.created_at >= '${sql(from)}'::timestamptz`);
if (to !== undefined) conditions.push(`e.created_at <= '${sql(to)}'::timestamptz`);
const where = conditions.length > 0 ? ` AND ${conditions.join(' AND ')}` : '';
const analyticsQuery = `WITH filtered AS (
  SELECT e.id,
         e.created_at,
         e.flow_type,
         e.status,
         e.duration_ms,
         e.cache_hit,
         COALESCE(t.model_requested, 'unknown') AS model,
         COALESCE(t.prompt_tokens, 0)::bigint AS prompt_tokens,
         COALESCE(t.completion_tokens, 0)::bigint AS completion_tokens,
         COALESCE(t.total_tokens, 0)::bigint AS total_tokens,
         COALESCE(t.cache_read_tokens, 0)::bigint AS cache_read_tokens,
         COALESCE(t.cost_usd, 0)::numeric AS cost_total_usd,
         COALESCE(t.input_cost_usd, 0)::numeric AS cost_input_usd,
         COALESCE(t.output_cost_usd, 0)::numeric AS cost_output_usd
  FROM executions e
  LEFT JOIN execution_telemetry t ON t.execution_id = e.id
  WHERE 1 = 1${where}
), totals AS (
  SELECT COUNT(*)::integer AS executions,
         COUNT(*) FILTER (WHERE status = 'success')::integer AS successful,
         COUNT(*) FILTER (WHERE status = 'failed')::integer AS failed,
         COUNT(*) FILTER (WHERE cache_hit)::integer AS cache_hits,
         COALESCE(SUM(prompt_tokens), 0)::bigint AS prompt_tokens,
         COALESCE(SUM(completion_tokens), 0)::bigint AS completion_tokens,
         COALESCE(SUM(total_tokens), 0)::bigint AS total_tokens,
         COALESCE(SUM(cache_read_tokens), 0)::bigint AS cache_read_tokens,
         ROUND(COALESCE(SUM(cost_total_usd), 0), 8) AS cost_total_usd,
         ROUND(COALESCE(SUM(cost_input_usd), 0), 8) AS cost_input_usd,
         ROUND(COALESCE(SUM(cost_output_usd), 0), 8) AS cost_output_usd,
         COALESCE(ROUND(AVG(duration_ms)), 0)::integer AS average_duration_ms
  FROM filtered
), by_day_data AS (
  SELECT (created_at AT TIME ZONE 'America/Sao_Paulo')::date::text AS date,
         COUNT(*)::integer AS executions,
         COALESCE(SUM(total_tokens), 0)::bigint AS total_tokens,
         ROUND(COALESCE(SUM(cost_total_usd), 0), 8) AS cost_total_usd
  FROM filtered
  GROUP BY 1
  ORDER BY date
), by_flow_data AS (
  SELECT flow_type,
         COUNT(*)::integer AS executions,
         COALESCE(SUM(total_tokens), 0)::bigint AS total_tokens,
         ROUND(COALESCE(SUM(cost_total_usd), 0), 8) AS cost_total_usd
  FROM filtered
  GROUP BY flow_type
  ORDER BY flow_type
), by_model_data AS (
  SELECT model,
         COUNT(*)::integer AS executions,
         COALESCE(SUM(total_tokens), 0)::bigint AS total_tokens,
         ROUND(COALESCE(SUM(cost_total_usd), 0), 8) AS cost_total_usd
  FROM filtered
  GROUP BY model
  ORDER BY model
)
SELECT json_build_object(
  'totals', (SELECT row_to_json(totals) FROM totals),
  'by_day', COALESCE((SELECT json_agg(row_to_json(by_day_data) ORDER BY date) FROM by_day_data), '[]'::json),
  'by_flow', COALESCE((SELECT json_agg(row_to_json(by_flow_data) ORDER BY flow_type) FROM by_flow_data), '[]'::json),
  'by_model', COALESCE((SELECT json_agg(row_to_json(by_model_data) ORDER BY model) FROM by_model_data), '[]'::json)
) AS response;`;
return [{ json: { analytics_query: analyticsQuery } }];

const prepared = $('Prepare Analytics Query').first().json;
if (!prepared?.analytics_query) throw new Error('Analytics query was not prepared.');
return [{ json: prepared }];

const response = typeof $json.response === 'string' ? JSON.parse($json.response) : $json.response;
if (!response?.totals || !Array.isArray(response.by_day) || !Array.isArray(response.by_flow) || !Array.isArray(response.by_model)) throw new Error('Resposta agregada de analytics invalida.');
return [{ json: response }];
